entries[325020] = { ["name"] = "Nova des Aufstiegs", ["text"] = "Pakt-Fähigkeit\nSofort\nEntfesselt einen mächtigen Animaausbruch, der innerhalb von 8 Metern in Abhängigkeit von der Anzahl der Gegner bis zu (74% der Zaubermacht) Arkanschaden verursacht und bis zu 6 Verbündete in diesem Radius um (24% der Zaubermacht) Gesundheit heilt.\n\nGewährt pro Ziel, dem Schaden zugefügt wurde, 1 Stapel von 'Segen der Aufgestiegenen'." }
