entries[325028] = { ["name"] = "Todeschakram", ["text"] = "40 Meter Reichweite\nSofort 45 sek. Abklingzeit\nWirft ein tödliches Chakram auf Euer aktuelles Ziel, das rasch 7-mal (31.6% der Angriffskraft) Schattenschaden verursacht und auf weitere Ziele in der Nähe überspringt. Von 'Todeschakram' getroffene Ziele erleiden 10 Sek. lang 10% mehr körperlichen Schaden durch Euch und Eure Begleiter.\n\nJedes Mal, wenn das Chakram Schaden verursacht, wird sein Schaden um 15% erhöht und Ihr erzeugt 3 Fokus." }
