entries[326050] = { ["name"] = "Unerbittliches Fressen", ["text"] = "30 Meter Reichweite\nSofort\nEntzieht dem Ziel seinen Geist, fügt ihm während der Kanalisierung alle 5.2 Sek Schattenschaden zu, heilt dabei den Zaubernden und ruft gleichzeitig je einen Stapel von 'Riesiger Appetit' hervor. Hält bis Abbruch lang an." }
entries[326052] = { ["name"] = "Essenz destillieren", ["text"] = "30 Meter Reichweite\nKanalisiert (Wirken in 6 sek.)\nEntzieht dem Behälter der Kammer und dem Gefängnis die Essenz, sodass diese hervorbricht und 6 Sek. lang alle 2 Sek. eine Infusionskugel erschafft. Wenn Spielercharaktere diese berühren, werden sie mit ' Gabe der Infusorin ' erfüllt." }
entries[326053] = { ["name"] = "Finsternis (Sonne)", ["text"] = "Sofort\nNach 2 Einsätzen von 'Sternenfeuer' wird 'Zorn' 15 Sek. lang ermächtigt. Nach 2 Einsätzen von 'Zorn' wird 'Sternenfeuer' 15 Sek. lang ermächtigt.\n\nFinsternis (Sonne)\nNaturzauber verursachen 15 % zusätzlichen Schaden und der Schaden von 'Zorn' ist um 40 % erhöht.\n\nFinsternis (Mond)\nArkanzauber verursachen 15 % zusätzlichen Schaden und der Schaden, den 'Sternenfeuer' Gegnern in der Nähe zufügt, ist um 30 % erhöht." }
entries[326054] = { ["name"] = "Riesiger Appetit", ["text"] = "100 Meter Reichweite\nSofort\nDas Fressen erzeugt Stapel von 'Riesiger Appetit' und erhöht das Tempo so um 3%." }
entries[326055] = { ["name"] = "Finsternis (Mond)", ["text"] = "Sofort\nNach 2 Einsätzen von 'Sternenfeuer' wird 'Zorn' 15 Sek. lang ermächtigt. Nach 2 Einsätzen von 'Zorn' wird 'Sternenfeuer' 15 Sek. lang ermächtigt.\n\nFinsternis (Sonne)\nNaturzauber verursachen 15 % zusätzlichen Schaden und der Schaden von 'Zorn' ist um 40 % erhöht.\n\nFinsternis (Mond)\nArkanzauber verursachen 15 % zusätzlichen Schaden und der Schaden, den 'Sternenfeuer' Gegnern in der Nähe zufügt, ist um 30 % erhöht." }
entries[326056] = { ["name"] = "Animageschoss", ["text"] = "100 Meter Reichweite\nSofort\nEin Animaschuss fügt getroffenen Zielen Schattenschaden zu." }
